47: export function rotationAngle(config: RotatingConfig, elapsed: number): number {
48:   const phase = finite(config.phase);
49:   const speed = activeSpeed(config);
50:   if (speed === 0) return phase;
51:   const time = finite(elapsed);
52:   if (config.kind === 'pendulum') {
53:     const swing = finite(config.swingAngle, DEFAULT_SWING_ANGLE);
54:     return phase + swing * Math.sin(speed * time);
55:   }
56:   return phase + spinSign(config) * speed * time;
57: }
