59: export function armTipPosition(config: RotatingConfig, elapsed: number): Vec3 {
60:   const center = isFiniteVec3(config.center) ? cloneVec3(config.center) : vec3();
61:   const arm = vec3(finite(config.armLength), 0, 0);
62:   return addVec3(center, rotateAroundY(arm, rotationAngle(config, elapsed)));
