65: /** d(angle)/dt around the Y axis. */
66: function angularVelocity(config: RotatingConfig, elapsed: number): number {
67:   const speed = activeSpeed(config);
68:   if (speed === 0) return 0;
69:   const time = finite(elapsed);
70:   if (config.kind === 'pendulum') {
71:     const swing = finite(config.swingAngle, DEFAULT_SWING_ANGLE);
72:     return swing * speed * Math.cos(speed * time);
73:   }
