78:   const omega = angularVelocity(config, elapsed);
79:   if (omega === 0 || !isFiniteVec3(point) || !isFiniteVec3(config.center)) return vec3();
80:   const radius = subVec3(point, config.center);
81:   return { x: omega * radius.z, y: 0, z: -omega * radius.x };
