84: /**
85:  * Reflects the ball off the arm segment center..tip and adds the arm surface speed.
86:  * Returns null when the ball is further than hitRadius from that segment horizontally.
87:  */
88: export function deflectBall(
89:   config: RotatingConfig,
90:   position: Vec3,
91:   velocity: Vec3,
92:   elapsed: number,
93:   hitRadius: number,
94: ): Vec3 | null {
95:   if (config.enabled === false) return null;
96:   if (!isFiniteVec3(position) || !isFiniteVec3(velocity) || !isFiniteVec3(config.center)) return null;
97:   if (!Number.isFinite(hitRadius) || hitRadius <= 0) return null;
98: 
99:   const center = config.center;
100:   const tip = armTipPosition(config, elapsed);
101:   const armX = tip.x - center.x;
102:   const armZ = tip.z - center.z;
103:   const armLengthSq = armX * armX + armZ * armZ;
104: 
105:   const toBallX = position.x - center.x;
106:   const toBallZ = position.z - center.z;
107:   let along = armLengthSq > 1e-12 ? (toBallX * armX + toBallZ * armZ) / armLengthSq : 0;
108:   along = Math.min(1, Math.max(0, along));
109: 
110:   const offsetX = position.x - (center.x + armX * along);
111:   const offsetZ = position.z - (center.z + armZ * along);
112:   if (Math.hypot(offsetX, offsetZ) > hitRadius) return null;
113: 
114:   const armDir = normalizeVec3(vec3(armX, 0, armZ)) ?? vec3(1, 0, 0);
115:   let normal = vec3(-armDir.z, 0, armDir.x);
116:   if (offsetX * normal.x + offsetZ * normal.z < 0) normal = scaleVec3(normal, -1);
117: 
118:   const reflected = subVec3(velocity, scaleVec3(normal, 2 * dotVec3(velocity, normal)));
119:   return addVec3(reflected, surfaceVelocityAt(config, position, elapsed));
