1: import type { Vec3 } from '../contracts/math';
2: import { addVec3, cloneVec3, normalizeVec3, scaleVec3 } from './vec';
3: 
4: /** Kinematic obstacles driven purely by the hole clock. */
5: export type MoverKind = 'platform' | 'sliding-wall' | 'door';
6: 
7: /** What happens once the mover reaches the far end of its travel. */
8: export type MoverLoop = 'ping-pong' | 'loop' | 'once';
9: 
10: export interface MoverConfig {
11:   id: string;
12:   kind: MoverKind;
13:   origin: Vec3;
14:   axis: Vec3;
15:   distance: number;
16:   speed: number;
17:   phase?: number;
18:   loop?: MoverLoop;
19:   pauseSeconds?: number;
20:   enabled?: boolean;
21: }
22: 
23: export interface MoverSample {
24:   position: Vec3;
25:   velocity: Vec3;
26:   progress: number;
27: }
28: 
29: interface MoverTrack {
30:   direction: Vec3;
31:   travel: number;
32:   pause: number;
33: }
34: 
35: interface MoverPhase {
36:   progress: number;
37:   sign: number;
38: }
39: 
40: function zeroVec(): Vec3 {
41:   return { x: 0, y: 0, z: 0 };
42: }
43: 
44: function staticSample(config: MoverConfig): MoverSample {
45:   return { position: cloneVec3(config.origin), velocity: zeroVec(), progress: 0 };
46: }
47: 
48: /** Returns null when the mover cannot move at all and has to be treated as static. */
49: function resolveTrack(config: MoverConfig): MoverTrack | null {
50:   if (config.enabled === false) return null;
51:   if (!Number.isFinite(config.distance) || !Number.isFinite(config.speed)) return null;
52:   if (config.distance <= 0 || config.speed <= 0) return null;
53:   const direction = normalizeVec3(config.axis);
54:   if (!direction) return null;
55:   const rawPause = config.pauseSeconds ?? 0;
56:   const pause = Number.isFinite(rawPause) && rawPause > 0 ? rawPause : 0;
57:   return { direction, travel: config.distance / config.speed, pause };
58: }
59: 
60: function wrap(value: number, period: number): number {
61:   return ((value % period) + period) % period;
62: }
63: 
64: /**
65:  * Maps mover time to a 0..1 position along the axis plus the sign of the motion.
66:  * A sign of 0 means the mover is parked at one of the ends.
67:  */
68: function resolvePhase(loop: MoverLoop, time: number, travel: number, pause: number): MoverPhase {
69:   if (loop === 'once') {
70:     if (time <= 0) return { progress: 0, sign: 0 };
71:     if (time >= travel) return { progress: 1, sign: 0 };
72:     return { progress: time / travel, sign: 1 };
73:   }
74: 
75:   if (loop === 'loop') {
76:     const local = wrap(time, travel + pause);
77:     if (local < travel) return { progress: local / travel, sign: 1 };
78:     return { progress: 1, sign: 0 };
79:   }
80: 
81:   let local = wrap(time, 2 * travel + 2 * pause);
82:   if (local < travel) return { progress: local / travel, sign: 1 };
83:   local -= travel;
84:   if (local < pause) return { progress: 1, sign: 0 };
85:   local -= pause;
86:   if (local < travel) return { progress: 1 - local / travel, sign: -1 };
87:   return { progress: 0, sign: 0 };
88: }
