90: /**
91:  * Samples the mover at `elapsed` seconds of hole time. The result depends only on
92:  * the clock, so every client driving the same config stays in sync without state.
93:  */
94: export function sampleMover(config: MoverConfig, elapsed: number): MoverSample {
95:   const track = resolveTrack(config);
96:   if (!track) return staticSample(config);
97: 
98:   const phase = config.phase ?? 0;
99:   if (!Number.isFinite(elapsed) || !Number.isFinite(phase)) return staticSample(config);
100: 
101:   const step = resolvePhase(config.loop ?? 'ping-pong', elapsed + phase, track.travel, track.pause);
102:   return {
103:     position: addVec3(config.origin, scaleVec3(track.direction, config.distance * step.progress)),
104:     velocity: step.sign === 0 ? zeroVec() : scaleVec3(track.direction, step.sign * config.speed),
105:     progress: step.progress,
106:   };
107: }
