109: /** Velocity a ball inherits from the mover while it rides on it. */
110: export function carryVelocity(config: MoverConfig, elapsed: number, contact: boolean): Vec3 {
111:   if (!contact) return zeroVec();
112:   return sampleMover(config, elapsed).velocity;
113: }
